    c.del_flag = '0'
    and c.term_id = #{termId}
    and c.teacher_id = #{teacherId}
    and (c.class_id = #{classId}
        or exists (select 1 from edu_course_class cc
                   where cc.course_id = c.course_id and cc.class_id = #{classId}))
    and c.status = #{status}

        and c.course_code like concat('%', #{courseCode}, '%')


        and c.course_name like concat('%', #{courseName}, '%')


order by c.term_id desc, c.course_code

mapper.update:
update edu_course
course_code = #{courseCode}, course_name = #{courseName}, term_id = #{termId}, teacher_id = #{teacherId}, class_id = #{classId}, cover = #{cover}, intro = #{intro}, status = #{status}, publish_time = #{publishTime}, update_by = #{updateBy}, update_time = sysdate()
where course_id = #{courseId}

